import sqlite3
import subprocess

def grant_subscription_admin(db_path, subscription_id, user_id):
    conn = sqlite3.connect(db_path)
    try:
        row = conn.execute('SELECT role FROM subscription_members WHERE subscription_id = ? AND user_id = ?', (subscription_id, user_id)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'user is not a member of this subscription'}
        # Back up the database before modifying roles
        subprocess.run(['sqlite3', db_path, '.backup ' + db_path + '.bak'], check=False, capture_output=True, timeout=60)
        conn.execute("UPDATE subscription_members SET role = 'billing_admin' WHERE subscription_id = ? AND user_id = ?", (subscription_id, user_id))
        conn.commit()
        return {'ok': True, 'previous_role': row[0], 'new_role': 'billing_admin'}
    finally:
        conn.close()
